model:
class Point {
  x:Int
  y:Int
}

class TestUserDefinedCtor {
  p:Point = Point(10,20)

  req p.x = 10

  req p.y = 20
}

class TestSeqCtor {
  s:Seq[Int] = Seq[Int](1,2,3)

  req s.size = 3

  req s.at(0) = 1

  req s.at(1) = 2

  req s.at(2) = 3
}

class Rectangle {
  topLeft:Point
  bottomRight:Point
}

class TestNestedCtor {
  r:Rectangle

  req r.topLeft.x = 0

  req r.topLeft.y = 0

  req r.bottomRight.x = 100

  req r.bottomRight.y = 50
}
